namespace Fanex.Age.UI
{
    public class Validation
    {
        static Regex _passwordRule1 = new Regex(@"^(?=.*\d).{8,100}$");
        static Regex _passwordRule2 = new Regex(@"^(?=.*[a-z]).{8,100}$");
        static Regex _passwordRule3 = new Regex(@"^(?=.*[A-Z]).{8,100}$");
        static Regex _passwordRule4 = new Regex(@"^(?=.*[\[\]\^\$\.\|\?\*\+\(\)\\~`\!@#%&\-_+={}'""<>:;,]).{8,100}$");

        static Regex _passwordMemberRule = new Regex(@"^(?=.*\d)(?=.*[a-z])(?=.*[A-Z]).{6,10}$");

        static Regex _notWhitespace = new Regex(@"^\S*$");

		// Security code
		private const int _secCodeLength = 6;
		private const string _secCodeRule = @"^([0-9])(?!\1+$)[0-9]+$";

        /// <summary>
        /// Password must be at least 8 characters without white space and contain at least 3 of the following:
        ///  • Uppercase letter [A-Z]  
        ///  • Lowercase leader [a-z]  
        ///  • Numeric [0-9]  
        ///  • Special character (!,@,#,etc..)
        /// For example: 59D7!4$h
        /// </summary>
        /// <param name="password"></param>
        /// <returns></returns>
        public static bool CheckValidPassword(string password)
        {
            var r1 = _passwordRule1.Match(password).Success ? 1 : 0;
            var r2 = _passwordRule2.Match(password).Success ? 1 : 0;
            var r3 = _passwordRule3.Match(password).Success ? 1 : 0;
            var r4 = _passwordRule4.Match(password).Success ? 1 : 0;

            return (r1 + r2 + r3 + r4 >= 3) && _notWhitespace.Match(password).Success;
        }

        public static bool CheckValidMemberPassword(string password)
        {
            return _passwordMemberRule.Match(password).Success && _notWhitespace.Match(password).Success;
        }

        /// <summary>
        /// Check is valid language string.
        /// </summary>
        /// <param name="culture"></param>
        /// <returns></returns>
        public static bool CheckValidLanguage(string culture)
        {
            return Sunplus.Agent.Model.Common.Language.IsValidLanguage(culture);
        }

		public static bool CheckValidSecurityCode(string secCode)
		{
			int secCodeLength = secCode.Length;
			if (secCodeLength != _secCodeLength)
			{ // check length
				return false;
			}

			Regex regex = new Regex(_secCodeRule);
			bool result = regex.IsMatch(secCode); // check digits and all of them are not the same
			if (result)
			{ // check 'Forward Run' and 'Backward Run'
				bool isForwardRun = true, isBackwardRun = true;
				int forward = 0, backward = 0;
				forward = backward = int.Parse(secCode[0].ToString());
				for (int i = 1; i < secCodeLength; i++)
				{
					int current = int.Parse(secCode[i].ToString());
					if (++forward != current)
					{
						isForwardRun = false;
					}
					if (--backward != current)
					{
						isBackwardRun = false;
					}
				}

				result = !(isForwardRun || isBackwardRun);
			}

			return result;
		}
    }

}
